diff --git a/calendar/base/content/today-pane-agenda.js b/calendar/base/content/today-pane-agenda.js
index 865676e3333..236241f2bd7 100644
--- a/calendar/base/content/today-pane-agenda.js
+++ b/calendar/base/content/today-pane-agenda.js
@@ -78,6 +78,17 @@
         window.addEventListener("unload", () => CalMetronome.off("minute", metronomeCallback));
       }

+      /**
+       * Ensure the agenda has been initialized, unless no calendars are active.
+       * If a calendar becomes active, this will be called again by CalendarDeactivator.
+       */
+      async ensureInitialized() {
+        if (!this.isActive && !document.documentElement.hasAttribute("calendar-deactivated")) {
+          Glean.calendar.viewInitialized.agenda.add(1);
+          await this.activate();
+        }
+      }
+
       /**
        * Implementation as required by CalendarFilteredViewMixin.
        */
@@ -175,8 +186,7 @@
         if (this.isActive) {
           await this.refreshItems();
         } else {
-          Glean.calendar.viewInitialized.agenda.add(1);
-          await this.activate();
+          await this.ensureInitialized();
         }
         this.selectedIndex = 0;
       }
